import{_ as s,l as o,o as e,c as l,v as t,p as T,x as r,d as p,i as P,S as M}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"SMTP / IMAP","description":"","frontmatter":{"title":"SMTP / IMAP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/smtp-imap.md","filePath":"cs/smtp-imap.md","lastUpdated":1789023840000}'),n={name:"cs/smtp-imap.md"};function A(d,a,S,h,m,c){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="smtp-imap" tabindex="-1">SMTP / IMAP <a class="header-anchor" href="#smtp-imap" aria-label="Permalink to &quot;SMTP / IMAP&quot;">​</a></h1><div class="epigraph"><p>SMTP 在 MTA 之间推送邮件；IMAP 让客户端在服务器上管理邮箱。提交与投递端口、TLS 时机不同，都不是 HTTP。</p><footer>—— 据 RFC 5321 SMTP；RFC 9051 IMAP4rev2 整理</footer></div><p><a href="/cs/geodns">上一课</a> 不传邮箱。<a href="/cs/dns-rr">DNS MX</a> 已点名记录。缺口是<strong>邮件运输与存取</strong>：SMTP 对话、IMAP 选文件夹。本课不把 SPF 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>邮件要跨管理域、要存、要多设备。SMTP：MAIL FROM、RCPT TO、DATA，MTA 跳到跳，MX 决定下一跳。提交（587）与传输（25）政策不同。IMAP：TCP 上命令取消息，状态在服务器；POP 对照为下载删除，点名。持久连接、大附件 MTU、超时与无线半开都出现。不是 REST 资源模型。</p><p>不要把 Gmail 网页当协议。</p><p><span class="marginnote">RFC 5321。STARTTLS 升级。本课不把每条 SMTP 代码背完。</span></p><h3 id="投递链与邮箱存取" tabindex="-1">投递链与邮箱存取 <a class="header-anchor" href="#投递链与邮箱存取" aria-label="Permalink to &quot;投递链与邮箱存取&quot;">​</a></h3><p>SMTP 跳到跳，IMAP 状态在服务器。逐跳 TLS 不是端到端密信。网页邮箱不是协议。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：MUA → 提交 → MTA 链 → 投递 → IMAP 取。对照 HTTP POST：无统一缓存，有队列与重试。与 QUIC：邮件仍多 TCP。</p>',11)),(e(),T(M,null,{default:r(()=>[P(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MUA%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%20--%3E%20SUB%5B%22SMTP%20%E6%8F%90%E4%BA%A4%22%5D%0A%20%20SUB%20--%3E%20MTA%5B%22MTA%20%E5%88%B0%20MTA%22%5D%0A%20%20MTA%20--%3E%20STORE%5B%22%E9%82%AE%E7%AE%B1%E5%AD%98%E5%82%A8%22%5D%0A%20%20STORE%20--%3E%20IMAP%5B%22IMAP%20%E5%AD%98%E5%8F%96%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DNS 缓存 MX 影响切换。TLS 对 SMTP 是逐跳，不是端到端密信（那是 OpenPGP/S/MIME，点名）。负载均衡对 25 端口要小心会话。分块附件像 HTTP 体，但边界是 MIME。</p><p>垃圾与伪造下一课认证。保活防止 NAT 拆 IMAP。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 JMAP 的全部。SPF/DKIM/DMARC 是下一课。后课默认：SMTP 推送投递；IMAP 远程邮箱。</p><p>把 25 对全世界开放中继会成为垃圾跳板。</p><p>上一课留下的缺口在本课收口；「SMTP / IMAP」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/spf-dkim-dmarc">SPF / DKIM / DMARC</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SMTP 管投递链；IMAP 管邮箱访问。</li><li>MX 与逐跳 TLS 是核心机制。</li><li>与 HTTP 会话模型不同。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 5321；RFC 9051。</li></ul>',10))])}const I=s(n,[["render",A]]);export{E as __pageData,I as default};
